// src/engine/orders/the-facts-the-explore-and-search-orders-lines-record.ts
/** The sites a hero's exploring brings to light, copied as the line is told. */
function theSitesFoundAsTheLineNamesThem(sites) {
	return sites.map((f) => ({
		name: f.name,
		isARitualSite: !!f.ritualSite,
		guardianName: f.monster?.name ?? null
	}));
}
