var CONSEC_CAPTURE_XP_PCT_BY_ALIGNMENT = {
	Undead: 100,
	Evil: 50
};
function consecCaptureXpPct(pl) {
	return (pl && CONSEC_CAPTURE_XP_PCT_BY_ALIGNMENT[pl.alignment]) ?? 0;
}
function consecratedIds(pl) {
	if (!pl) return [];
	if (!Array.isArray(pl.consecratedProvIds)) pl.consecratedProvIds = [];
	return pl.consecratedProvIds;
}
function isConsecrated(pl, provId) {
	return consecratedIds(pl).includes(provId);
}
function ownedConsecratedProvs(state, pi) {
	const pl = (state.players ?? [])[pi];
	if (!pl) return [];
	return consecratedIds(pl).map((id) => state.world.provinces[id]).filter((pv) => pv?.owner === pi);
}
function nearestConsecratedProv(state, pi, fromProvId) {
	const list = ownedConsecratedProvs(state, pi);
	if (!list.length) return null;
	const from = fromProvId != null ? state.world.provinces[fromProvId] : null;
	if (!from) return list[0];
	let best = null, bd = Infinity;
	list.forEach((pv) => {
		const d = hexDistP(from, pv, state.world.cols);
		if (d < bd || d === bd && (pv.tax || 0) > (Number(best?.tax) || 0)) {
			bd = d;
			best = pv;
		}
	});
	return best;
}
function demoteGuardToWanderer(h) {
	if (!h) return;
	h._isNeutralGuard = false;
	h.name = (h.name ?? "").replace(/\s*\(wandering\)/gi, "").trim() + " (wandering)";
}
function claimWandererName(h) {
	if (!h) return;
	h.name = (h.name ?? "").replace(/\s*\(wandering\)/gi, "").trim();
}
function normaliseOwnedNames(gs) {
	let n = 0;
	(gs.characters ?? []).forEach((c) => {
		if (c?.player == null) return;
		if (/\(wandering\)/i.test(c.name ?? "")) {
			claimWandererName(c);
			n++;
		}
	});
	return n;
}
function normaliseStrandedGuards(gs) {
	let n = 0;
	(gs.characters ?? []).forEach((c) => {
		if (c?.player !== null || !c.alive || !c._isNeutralGuard) return;
		const pv = (gs.world?.provinces ?? [])[c.location];
		if ((c.armies ?? []).length === 0 || pv?.owner != null) {
			demoteGuardToWanderer(c);
			n++;
		}
	});
	return n;
}
function provinceConsecrated(gs, prov) {
	if (prov?.owner == null) return false;
	const owner = gs?.players?.[prov.owner];
	return !!owner && isConsecrated(owner, prov.id);
}
function relOfReport(gs, a, b) {
	if (a == null || b == null || a === b) return "neutral";
	const k = a < b ? `${String(a)}-${String(b)}` : `${String(b)}-${String(a)}`;
	return (gs.relations?.[k] ?? "") || "neutral";
}
function detRoll(turn, viewerPi, charId, provId) {
	let h = 2166136261;
	const s = `${String(turn)}|${String(viewerPi)}|${String(charId)}|${String(provId)}`;
	for (let i = 0; i < s.length; i++) {
		h ^= s.charCodeAt(i);
		h = Math.imul(h, 16777619) >>> 0;
	}
	return (h >>> 0) / 4294967296;
}
function spotEnemyInOwnedProvince(gs, viewerPi, prov, enemyChar, turn) {
	const explored = 100;
	const enemySpy = Math.min(5, Number(enemyChar.skills?.spy) || 0);
	let friendlySpy = 0;
	(prov.characters ?? []).forEach((cid) => {
		const f = gs.characters[cid];
		if (!f || !f.alive || f.player == null) return;
		if (f.player === viewerPi || relOfReport(gs, viewerPi, f.player) === "allied") friendlySpy = Math.max(friendlySpy, Number(f.skills?.spy) || 0);
	});
	friendlySpy = Math.min(5, friendlySpy);
	let chance = Math.max(25, Math.min(95, explored - 20 * enemySpy + 10 * friendlySpy + whatARealmsDiscoveriesAddToSpottingALurker(gs.players?.[viewerPi], {
		theGround: prov.terrain,
		isItTheRealmsHome: () => homeFounderOf(gs, prov.id) === viewerPi,
		isItCoastal: () => discProvCoastal(gs, prov)
	})));
	if (perkTier(enemyChar, "illusory") >= 1) chance = Math.max(5, chance * .5);
	return detRoll(turn ?? gs.turn, viewerPi, enemyChar.id, prov.id) * 100 < chance;
}
/** The consecrations a king may hold at once (plan P1-11e22, moved as it was; here since P1-11e24, where the views may ask it): his White, and what his realm's
*  discoveries add (ad03 Holy Sites, +1; still needs White 1+; the discoveries' registry's since plan P1-19ae:
*  "orderOutcome: a realm's discoveries add to the consecrations a crown may hold"). */
function theConsecrationsAKingMayHold(c, hisRealm) {
	return skillLevel(c, "white") + whatARealmsDiscoveriesAddToTheConsecrationsACrownMayHold(hisRealm, { theConsecratorsWhiteSkill: skillLevel(c, "white") });
}
