	idx.sort((a, b) => s.standings[b].score - s.standings[a].score || (s.taxByPlayer[b] || 0) - (s.taxByPlayer[a] || 0) || (s.goldByPlayer[b] || 0) - (s.goldByPlayer[a] || 0));
