function titleChangesTheTitlesEachRealmWonAndLostSinceLastTurn(turnContext) {
	const { G } = turnContext;
	const theTitlesRecord = G;
	let curMajor = {}, curMinor = {};
	try {
		const st = computeStandings(G);
		TITLE_DEFS.forEach((t) => {
			const h = st.titles[t.key] ?? {};
			curMajor[t.key] = {
				charId: h.charId ?? null,
				playerIndex: h.playerIndex ?? null,
				kingdomLevel: !!t.kingdomLevel
			};
		});
		const mh = computeMinorTitles(G);
		MINOR_TITLES.forEach((t) => {
			const h = mh[t.key] ?? {};
			curMinor[t.key] = {
				charId: h.charId ?? null,
				playerIndex: h.playerIndex ?? null
			};
		});
	} catch {
		curMajor = {};
		curMinor = {};
	}
	const prev = theTitlesRecord._titlesSnapshot ?? null;
	const nowPublic = (G.turn || 1) >= TITLES_PUBLIC_FROM_TURN || !!G.gameOver;
	const firstPublic = nowPublic && !prev?.wasPublic;
	const gainsByPlayer = {};
	const lossesByPlayer = {};
	if (nowPublic) {
		const chName = (id) => {
			const c = (asItsGuardReadsIt(G.characters) ?? []).find((x) => x.id === id);
			return c ? c.name : null;
		};
		const pName = (pi) => {
			const p = G.players[pi];
			return p ? p.name : null;
		};
		const recordLoss = (scope, t, cur, was) => {
			if (firstPublic) return;
			const hadHolder = t.kingdomLevel ? was.playerIndex != null : was.charId != null;
			const nowDifferent = t.kingdomLevel ? cur.playerIndex !== was.playerIndex : cur.charId !== was.charId;
			if (!hadHolder || !nowDifferent) return;
			const loserPi = was.playerIndex;
			if (loserPi == null || loserPi === cur.playerIndex) return;
			const itsLosses = lossesByPlayer[loserPi] ?? [];
			lossesByPlayer[loserPi] = itsLosses;
			itsLosses.push({
				scope,
				key: t.key,
				name: t.name,
				kingdomLevel: !!t.kingdomLevel,
				vacant: cur.playerIndex == null,
				newHolderIndex: cur.playerIndex ?? null,
				newHolderName: cur.playerIndex != null ? pName(cur.playerIndex) : null,
				newCharName: t.kingdomLevel || cur.charId == null ? null : chName(cur.charId)
			});
		};
		TITLE_DEFS.forEach((t) => {
			const cur = curMajor[t.key] ?? {}, was = prev?.major?.[t.key] ?? {};
			if (firstPublic ? cur.playerIndex != null : t.kingdomLevel ? cur.playerIndex != null && cur.playerIndex !== was.playerIndex : cur.charId != null && cur.charId !== was.charId) {
				const pi = cur.playerIndex;
				if (pi != null) {
					const itsGains = gainsByPlayer[pi] ?? [];
					gainsByPlayer[pi] = itsGains;
					itsGains.push({
						scope: "major",
						key: t.key,
						name: t.name,
						charName: t.kingdomLevel ? null : chName(cur.charId),
						kingdomName: pName(pi),
						kingdomLevel: !!t.kingdomLevel,
						perk: t.perk,
						req: t.req,
						initial: firstPublic
					});
				}
			}
			recordLoss("major", t, cur, was);
		});
		MINOR_TITLES.forEach((t) => {
			const cur = curMinor[t.key] ?? {}, was = prev?.minor?.[t.key] ?? {};
			if (firstPublic ? cur.charId != null : cur.charId != null && cur.charId !== was.charId) {
				const pi = cur.playerIndex;
				if (pi != null) {
					const itsGains = gainsByPlayer[pi] ?? [];
					gainsByPlayer[pi] = itsGains;
					itsGains.push({
						scope: "minor",
						key: t.key,
						name: t.name,
						charName: chName(cur.charId),
						kingdomName: pName(pi),
						perk: t.perk,
						req: t.req,
						initial: firstPublic
					});
				}
			}
			recordLoss("minor", t, cur, was);
		});
	}
	theTitlesRecord._titleGainsByPlayer = gainsByPlayer;
	theTitlesRecord._titleLossesByPlayer = lossesByPlayer;
	theTitlesRecord._titlesSnapshot = {
		major: curMajor,
		minor: curMinor,
		wasPublic: nowPublic
	};
}
// src/engine/run-turn.ts
function resolveTurn(save, freshPlayers, expectedTurnToRun, seed) {
	const turnDice = seed == null ? null : kcRngStream(seed);
	const onTheTurnsDice = (fn) => {
		if (!turnDice) return fn();
		const was = kcRng.use(turnDice);
		try {
			return fn();
		} finally {
			kcRng.use(was);
		}
	};
	return onTheTurnsDice(() => {
		let whatTheSavesUpgradeFound;
		let G;
		try {
			const parsed = typeof save === "string" ? JSON.parse(save) : save;
			refuseASaveThatIsNotAGameInPlay(parsed);
			G = parsed;
			seedUsedArmyNames(G);
			seedUsedHeroNames(G);
			whatTheSavesUpgradeFound = upgradeGameState(G);
			snapshotHeldItems(G);
			lastTurnsBattleAndDuelSwordsClearedFromTheMap(G);
		} catch (e) {
			throw new Error(`Could not read the saved game: ${theWordsOfWhatWasThrown(e)}`, { cause: e });
		}
		const turnContext = createTurnContext(G, freshPlayers, expectedTurnToRun, whatTheSavesUpgradeFound);
		const { _tel } = turnContext;
		try {
			G.players.forEach((pl, pi) => {
				if (pl) _tel.pre[pi] = telRealmSnapshot(G, pi);
			});
		} catch (_te) {
			console.warn("telemetry pre-snapshot:", _te);
		}
		const { _botPlayerIdx, _botEncounteredAtStart } = turnContext;
		everyRealmStampedBotOrHumanFromTheBotSlotRows(turnContext);
		_botPlayerIdx.forEach((idx) => {
			_botEncounteredAtStart[idx] = [...G.players[idx]?._encountered ?? []];
		});
		turnStartRepairsAndAFreshSlateOfOrdersForEveryHero(turnContext);
		mergeTheRealmsSubmittedOrdersDeclarationsMessagesAndEncounterPlans(turnContext);
		ensureAllLairHoards(G);
		const { turnLog } = turnContext;
		relationsReadyAndLastTurnsResearchChoicesSettledWithTheBotsOwnPicks(turnContext);
		botDiplomacyTreatsAndWarsByAlignmentTheGrudgeAndAReckoningClaim(turnContext);
		warWithoutWarningTitlesHeldSafeStartAndStaleOrderLinesGmRemovalsAndMessages(turnContext);
		movePoolsPerTurnTrackersEspionageResetsAndTheSaveSweepsBeforeTheBotsPlan(turnContext);
		botRealmsPlanTheTurnConcessionsMovementMusterEconomyActionsSpringOrdersHygieneAndTheReckoning(turnContext);
		missingOrdersDefaultToDefendTheOrdersRecordAndTheWarFrontsAtTheStart(turnContext);
		for (let ph = 0; ph < 5; ph++) {
			turnContext._currentPhase = ph;
			const _phaseStartLoc = {};
			G.characters.forEach((c) => {
				if (c?.alive) _phaseStartLoc[c.id] = c.location;
			});
			startPhaseHealingSnapshotsAndStalledBattles(turnContext, ph);
			const intents = buildPhaseIntents(turnContext, ph);
			pinAndReactToPhaseIntents(turnContext, ph, intents);
			resolvePhaseOrdersInTwoTiersAroundTheDefendStep(turnContext, ph, intents);
			endPhaseSkillRisesFallenCommandersAndProvinceMemory(turnContext, ph, _phaseStartLoc);
			if (ph === 4) earlyWinterCharmsFadeTaxesWagesRaidersMusterAndGarrisonDrill(turnContext);
			syncAllMaxHp(turnContext);
		}
		turnContext._currentPhase = null;
		turnContext._afterPhases = true;
		afterThePhasesStandOffsTheDeadGravesCouriersMassHealingCowardsAndLocationNames(turnContext);
		botDiplomacyTreatsAndWarsByAlignmentTheGrudgeAndAReckoningClaim(turnContext);
		diplomacyResolutionOverturesPeaceAlliancesWarAndWarFrontWarnings(turnContext);
		victoryTheReckoningEliminationConcessionAndTheAnnouncement(turnContext);
		newTurnCounterKingSuccessionSummonsAndSpellsEndAndTheGrandDesigns(turnContext);
		newTurnWarAcademyInformantsDivineResurrectionGravesMercenariesWanderersAndTheFinalReconcile(turnContext);
		imperialTitleIntelEachHoldersReportOnRivalRealmsAndTheLoremastersCopy(turnContext);
		titleChangesTheTitlesEachRealmWonAndLostSinceLastTurn(turnContext);
		return {
			state: JSON.stringify(G),
			log: turnLog,
			spyStealthAndInvisibilityStampedForTheReports: () => {
				onTheTurnsDice(() => {
					spyStealthAndInvisibilityStampedForTheReports(turnContext);
				});
			},
			whatTheReportsRead: () => whatTheReportsRead(turnContext),
			whereTheSaveDiffersFromThisBuildsSchema: whatTheSavesUpgradeFound.whereTheSaveDiffersFromThisBuildsSchema
		};
	});
}
/** The words of what a read of the save threw, as `${(e && e.message) || e}` wrote them: its message, else itself (an
*  error of another realm's class too: a test's engine runs in a vm). */
function theWordsOfWhatWasThrown(e) {
	let words = e;
	if (e) {
		const message = Reflect.get(Object(e), "message");
		if (message) words = message;
	}
	return String(words);
}
function spyStealthAndInvisibilityStampedForTheReports(turnContext) {
	const { _reports, G } = turnContext;
	if (_reports.stealthRolled) throw new Error("the Spy stealth is rolled once a turn");
	_reports.stealthRolled = true;
	(asItsGuardReadsIt(G.characters) ?? []).forEach((c) => {
		if (!c?.alive) return;
		if (c._invisTurn === G.turn - 1) {
			c._invisTurn = G.turn;
			c._unspottedTurn = G.turn;
		}
		const _lvl = Math.min(5, effStat(turnContext, c, "spy"));
		const _shimmer = perkTier(c, "illusory") >= 1;
		if (_lvl <= 0 && !_shimmer) return;
		let _seenPct = 100 - _lvl * 5;
		if (_shimmer) _seenPct = _seenPct * .5;
		if (d100() > _seenPct) {
			c._unspottedTurn = G.turn;
			emit(turnContext, {
				type: "system",
				fact: {
					kind: "a hero moves unseen this turn",
					heroName: c.name,
					byTheShimmer: _shimmer,
					spyLevel: _lvl
				},
				audience: {
					actor: c.player,
					realms: [c.player]
				},
				hero: c.id,
				phase: 0
			});
		}
	});
}
function whatTheReportsRead(turnContext) {
	const { _reports, freshPlayers, G, turnLog, presenceByPhase, battleCommanders, clairWatch, _tel } = turnContext;
	if (_reports.built) throw new Error("buildReports() runs once a turn");
	if (!_reports.stealthRolled) throw new Error("the Spy stealth is rolled before buildReports()");
	_reports.built = true;
	return {
		freshPlayers,
		G,
		turnLog,
		sight: {
			presenceByPhase,
			battleCommanders,
			clairWatch
		},
		_tel
	};
}
