/** How many of the check's findings the GM is shown by name: the rest are counted. */
var THE_CHECKS_FINDINGS_NAMED_AT_MOST = 10;
/** "1 thing", "2 things". */
var theCountOf = (findings) => findings.length === 1 ? "1 thing" : `${String(findings.length)} things`;
/** The first ten of the findings, joined, and how many more. */
var theListOf = (findings) => {
	const more = findings.length - THE_CHECKS_FINDINGS_NAMED_AT_MOST;
	return findings.slice(0, THE_CHECKS_FINDINGS_NAMED_AT_MOST).join("; ") + (more > 0 ? `; and ${String(more)} more.` : ".");
};
/** The check's findings in words: how many, that the turn ran on the save as it was, the first ten, and how many more. */
function whatTheSavesCheckFoundInWords(findings) {
	return `The saved game holds ${theCountOf(findings)} this build of Kingdoms Call doesn't know, and the turn ran on it as it was. Please send this list to the Kingdoms Call team: ${theListOf(findings)}`;
}
/** Why the check stopped the turn, in words: how many places, that the turn didn't run, the first ten, how many more. */
function whyTheSavesCheckStoppedTheTurnInWords(findings) {
	return `The saved game holds ${theCountOf(findings)} this build of Kingdoms Call doesn't know, so the turn did not run. Please send this list to the Kingdoms Call team: ${theListOf(findings)}`;
}
