/** The words of the Spy stealth's line (its one kind). */
function theWordsOfTheSpyStealthLine(fact) {
	return `[Intelligence] 🕶 ${fact.heroName} moved unseen this turn — ${fact.byTheShimmer ? "the Shimmer of illusory magic blurred them from watching eyes" : "Spy " + String(fact.spyLevel) + " kept them out of enemy sightings"}.`;
}
// src/views/prose/the-words-of-each-line.ts
/** An area's words, as the route reads them: for each of its kinds (by its audience table), the words of its facts. */
function theRouteToAnArea(audienceOfEachKind, wordsOf) {
	const isOneOfItsKinds = (fact) => Object.hasOwn(audienceOfEachKind, fact.kind);
	const words = (fact) => {
		if (!isOneOfItsKinds(fact)) throw new Error(`the route took "${fact.kind}" to an area that has no such kind`);
		return wordsOf(fact);
	};
	return Object.keys(audienceOfEachKind).map((kind) => [kind, words]);
}
